head.script:
scwin.gridView2_oneditkeydown = function(info) {
    console.log("gridView2_oneditkeydown");
    console.log("info.rowIndex : " + info.rowIndex);
    console.log("info.colIndex : " + info.colIndex);
    console.log("info.colID : " + info.colID);
    log = info.colID;
};
scwin.div_Search_btn_Search_onclick = function(e) {
    var row = dst_tr01_out01.insertRow();
    gridView2.setFocusedCell(0, 0, true);
};
scwin.keyboardBehaviour = function(id) {
    var img = WebSquare.wUnit.getDomById(id);
    var keyboardEvent = document.createEvent("KeyboardEvent");
    var initMethod = typeof keyboardEvent.initKeyboardEvent !== 'undefined' ? "initKeyboardEvent" : "initKeyEvent";
    keyboardEvent[initMethod](
        "keydown", // event type : keydown, keyup, keypress
        true, // bubbles
        true, // cancelable  
        window, // viewArg: should be window  
        false, // ctrlKeyArg  
        false, // altKeyArg
        false, // shiftKeyArg
        false, // metaKeyArg
        115, // keyCodeArg : unsigned long the virtual key code, else 0  
        115 // charCodeArgs : unsigned long the Unicode character associated with the depressed key, else 0
    );
    img.dispatchEvent(keyboardEvent);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 버튼을 클릭한다.
    //1. Run the sample file and click the button.
    //Verify step 1. The grid row is added and changed to edit mode.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('div_Search_btn_Search').click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView2__chk_col').css('display') == 'block'", "true");
    //Test step 2. 개발자모드 실행(F12)후 버튼을 클릭하여 컬럼을 클릭하고 키보드의 방향키를 좌우위아래로 수행한다.(oneditkeydown 이벤트 수행)
    //2. After executing developer mode (F12), click the button and click on the column and execute the direction key of the keyboard upside down (perform oneditkeydown event).
    //Verify step 2. You can see the value that shows colID (info.colID: chk_col) (previously shown as undefined because the engine has no function)
    WebSquare.wUnit.addCommand("set", "scwin.keyboardBehaviour('G_'+$p.id+'gridView2__chk_col')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'chk_col'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
